TEMPLATE_B64 = {
    "본사": BONSA_XLSX_B64,
    "직영": JIKYEONG_XLSX_B64,
    "소사장": SOSAJANG_XLSX_B64,
    "소사장실적": SOSAJANG_PERF_XLSX_B64,
}


def get_template_bytes(key):
    """양식 이름을 주면 엑셀 파일 내용(바이트)을 돌려줍니다."""
    if key not in TEMPLATE_B64:
        raise KeyError(f"모르는 양식입니다: {key}")
    return base64.b64decode(TEMPLATE_B64[key])
